import itertools
import heapq
from collections import Counter


def _temporal_solver(coupon_rule, minimum_duration, strict_deadline=False):
    def solve(data):
        required = data.get("required", [])
        required_bits = {name: 1 << i for i, name in enumerate(required)}
        full = (1 << len(required)) - 1
        start_node = data["source"]
        start_mask = required_bits.get(start_node, 0)
        limit = data["coupons"]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_time = data["start"]
        best = {(start_node, start_mask, 0): start_time}
        queue = [(start_time, start_node, start_mask, 0)]
        deadline = data["deadline"]
        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if best.get(state) != arrival:
                continue
            coupons_ok = used == limit if coupon_rule == "exact" else True
            if node == data["target"] and mask == full and coupons_ok:
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                # Close is an exclusive bound on departure, not arrival.
                if depart >= edge["close"]:
                    continue
                duration = edge["duration"]
                choices = [(duration, used)]
                if used < limit:
                    discounted = max(minimum_duration,
                                     duration - edge.get("discount", 0))
                    choices.append((discounted, used + 1))
                for travel_time, next_used in choices:
                    next_time = depart + travel_time
                    if (next_time > deadline if not strict_deadline
                            else next_time >= deadline):
                        continue
                    next_node = edge["v"]
                    next_mask = mask | required_bits.get(next_node, 0)
                    next_state = (next_node, next_mask, next_used)
                    if next_time < best.get(next_state, float("inf")):
                        best[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node,
                                               next_mask, next_used))
        return {"arrival": None}
    return solve


def _build_component_01():
    return _temporal_solver("at_most", 1)


def _build_component_02():
    return _temporal_solver("exact", 1)


def _build_component_03():
    return _temporal_solver("at_most", 2)


def _build_component_04():
    return _temporal_solver("exact", 2)


def _build_component_05():
