def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def event_amount(event, mode):
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        return -total if event.get("kind") == "refund" else total

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            revision_key = (event.get("revision", 0), position)
            if event_id not in chosen or revision_key > chosen[event_id][0]:
                chosen[event_id] = (revision_key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + event_amount(event, mode)
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        features = set(data.get("features", []))

        options = []
        rows_by_name_version = {}
        for name in names:
            versions = []
            for row in packages[name]:
                version = row["version"]
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                versions.append(version)
                rows_by_name_version[name, version] = row
            options.append([-1] + sorted(versions))

        roots = data["roots"]
        for vector in itertools.product(*options):
            selected = dict(zip(names, vector))
            if any(selected.get(name, -1) == -1 or
                   not bounds[0] <= selected[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue

            graph = {}
            valid = True
            for name, version in selected.items():
                if version == -1:
                    continue
                row = rows_by_name_version.get((name, version))
                if row is None:
                    valid = False
                    break
                deps = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    dep_name = dep["name"]
                    dep_version = selected.get(dep_name, -1)
                    if (dep_version == -1 or
                            not dep["min"] <= dep_version <= dep["max"]):
                        valid = False
                        break
                    deps.append(dep_name)
                graph[name] = deps
                if not valid:
                    break
            if not valid:
                continue

            # Only packages reachable through active dependencies of roots belong
            # in the installation; reject disconnected extras.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(graph.get(name, []))
            if any(version != -1 and name not in reachable
                   for name, version in selected.items()):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(dep) for dep in graph.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in reachable):
                continue
            return {"versions": {name: version for name, version in selected.items()
                                 if version != -1}}
        return {"error": "unsatisfiable"}
    return solve


def _build_component_08():
    def feasible(selection, data):
        ids = {job["id"] for job in selection}
        if not set(data.get("mandatory", [])).issubset(ids):
            return False
        counts = Counter(job["group"] for job in selection)
        for group, (low, high) in data.get("quotas", {}).items():
            if not low <= counts[group] <= high:
                return False

        ordered = sorted(selection, key=lambda job: (job["start"], job["end"]))
        end = None
        for job in ordered:
            if end is not None and job["start"] < end:
                return False
            end = job["end"]
        return True

    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        best_value = None
        best_ids = None
        for selection in itertools.combinations(jobs, k):
            if not feasible(selection, data):
                continue
            value = sum(job["value"] for job in selection)
            ids = tuple(sorted(job["id"] for job in selection))
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
    "component_03": _build_component_03(),
    "component_04": _build_component_04(),
    "component_05": _build_component_05(),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
